<script setup lang="ts">import{LockKeyhole,ShieldCheck,UserRound}from'lucide-vue-next';import{computed,reactive,shallowRef}from'vue';import{ElMessage}from'element-plus';import{useRoute,useRouter}from'vue-router';import{authApi,type CaptchaChallenge}from'@/api/auth';import{ApiError}from'@/api/http';import{useAuthStore}from'@/stores/authStore';import{useWorkspaceTabsStore}from'@/stores/workspaceTabs';import ProductLogo from'@/components/ProductLogo.vue';import image from'@/assets/login-illustration.png';const auth=useAuthStore(),workspaceTabs=useWorkspaceTabsStore(),router=useRouter(),route=useRoute(),busy=shallowRef(false),challenge=shallowRef<CaptchaChallenge|null>(null);const form=reactive({username:'',password:'',captchaAnswer:''}),password=reactive({currentPassword:'',newPassword:'',confirmPassword:''});const changing=computed(()=>auth.account?.mustChangePassword===true);async function refreshCaptcha(){try{challenge.value=await authApi.captcha(form.username)}catch(e){ElMessage.error(e instanceof Error?e.message:'验证码加载失败')}}async function login(){busy.value=true;try{const s=await auth.login(form.username,form.password,challenge.value?.id,form.captchaAnswer);workspaceTabs.closeAll();password.currentPassword=form.password;if(!s.mustChangePassword)await router.replace(typeof route.query.redirect==='string'?route.query.redirect:'/ask')}catch(e){if(e instanceof ApiError&&['CAPTCHA_REQUIRED','CAPTCHA_INVALID'].includes(e.code))await refreshCaptcha();ElMessage.error(e instanceof Error?e.message:'登录失败')}finally{busy.value=false}}async function change(){if(password.newPassword!==password.confirmPassword)return ElMessage.warning('两次密码不一致');busy.value=true;try{await auth.changePassword(password.currentPassword,password.newPassword);await router.replace('/ask')}catch(e){ElMessage.error(e instanceof Error?e.message:'修改失败')}finally{busy.value=false}}</script>
<template><main class="login-page"><section class="login-visual"><img :src="image" alt=""/></section><section class="login-content"><div class="login-stack"><div class="login-brand"><span class="login-logo"><ProductLogo /></span><span class="login-brand-text">代码知识平台</span></div><form v-if="!changing" class="login-card" @submit.prevent="login"><h1>登录</h1><label class="login-field"><UserRound :size="17"/><input v-model.trim="form.username" autocomplete="username" placeholder="用户名"/></label><label class="login-field"><LockKeyhole :size="17"/><input v-model="form.password" type="password" autocomplete="current-password" placeholder="密码"/></label><div v-if="challenge" class="captcha-row"><label class="login-field"><ShieldCheck :size="17"/><input v-model="form.captchaAnswer" placeholder="验证码答案"/></label><button class="captcha-image" type="button" @click="refreshCaptcha">{{challenge.prompt}}</button></div><button class="login-submit" :disabled="busy">{{busy?'登录中…':'登录'}}</button></form><form v-else class="login-card" @submit.prevent="change"><h1>首次登录，请修改密码</h1><p>密码修改完成前无法进入系统。</p><label class="login-field"><LockKeyhole :size="17"/><input v-model="password.currentPassword" type="password" autocomplete="current-password" placeholder="当前密码"/></label><label class="login-field"><LockKeyhole :size="17"/><input v-model="password.newPassword" type="password" autocomplete="new-password" placeholder="新密码（8–64 位，至少三类字符）"/></label><label class="login-field"><LockKeyhole :size="17"/><input v-model="password.confirmPassword" type="password" autocomplete="new-password" placeholder="确认新密码"/></label><button class="login-submit" :disabled="busy">{{busy?'保存中…':'保存新密码'}}</button></form><p class="login-footnote">HttpOnly Cookie 会话 · CSRF 保护 · 失败登录验证码</p></div></section></main></template>
